function parseLeadingInt(s: string): number {
  let i = 0;
  while (i < s.length && s[i] === " ") i++;
  let sign = 1;
  if (s[i] === "+" || s[i] === "-") {
    if (s[i] === "-") sign = -1;
    i++;
  }
  let value = 0;
  while (i < s.length && s[i] >= "0" && s[i] <= "9" && value <= 2147483648) {
    value = value * 10 + (s.charCodeAt(i) - 48);
    i++;
  }
  value *= sign;
  return Math.max(-2147483648, Math.min(2147483647, value)) || 0;
}

