function parseLeadingInt(s: string): number {
  const MAX = 2147483647, MIN = -2147483648;
  let i = 0;
  while (i < s.length && s[i] === " ") i++;
  let sign = 1;
  if (s[i] === "+" || s[i] === "-") {
    if (s[i] === "-") sign = -1;
    i++;
  }
  let result = 0;
  while (i < s.length && s[i] >= "0" && s[i] <= "9") {
    const d = s.charCodeAt(i) - 48;
    // result * 10 + d > MAX  <=>  result > (MAX - d) / 10
    if (result > Math.floor((MAX - d) / 10)) return sign === 1 ? MAX : MIN;
    result = result * 10 + d;
    i++;
  }
  return sign === 1 ? result : -result || 0;
}

